C='../../prototype/clips/'
def vid(n,poster=True): return f'<video style="background:url({C}{n}.jpg) center/cover" autoplay muted loop playsinline preload="metadata" poster="{C}{n}.jpg"><source media="(max-width:768px)" src="{C}{n}-960.mp4" type="video/mp4"><source src="{C}{n}-1920.webm" type="video/webm"><source src="{C}{n}-1920.mp4" type="video/mp4"></video>'
def head(t,on): return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{t} | Imperial Yachting</title>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;1,300&family=Inter:wght@400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="../pages.css"></head><body>
<nav><a class="logo" href="#">IMPERIAL</a><div class="links cap">{''.join(f'<a class="{"on" if x==on else ""}" href="#">{x}</a>' for x in ["Fleet","Services","Destinations","Partners","Journal","Contact"])}</div><span class="burger cap">Menu</span></nav>'''
FOOT='''<footer class="cap"><span>Imperial Yachting · Dubai Harbour</span><span>booking@imperialyachting.com · +971 52 835 5939</span><span>Licence 960574</span></footer><a class="wa" href="https://wa.me/971528355939">WA</a><script>const w=document.querySelector(".wa"),f=()=>w.style.opacity=scrollY>innerHeight*.8?1:0;w.style.transition="opacity .4s";addEventListener("scroll",f);f()</script></body></html>'''
def cta(clip,title): return f'<section class="cta">{vid(clip)}<div class="in"><h2 class="serif">{title}</h2><a class="btn" href="https://wa.me/971528355939">Write on WhatsApp</a> &nbsp; <a class="btn o" href="#">booking@imperialyachting.com</a></div></section>'
svc=[("Yacht Charter","Day, weekly, and monthly luxury yacht charters with professional crew. All-inclusive packages on our owned fleet of premium motor yachts.","vd40-aerial","Charter"),
("Yacht Management","Comprehensive fleet management for yacht owners, from charter revenue optimization and crew management to maintenance and accounting.","moneta-golden","Management"),
("Cinematography","Professional yacht-based film production, drone footage, and content creation for brands, events, and social media through our Cinematographic Bureau.","evo43-run","Cinematography"),
("Brandwave","Full-service yacht branding and marketing: brand identity, yacht wrapping, digital campaigns, and luxury brand positioning.","ilia-harbour","brandwave.imperialyachting.com")]
rows=''.join(f'<div class="row"><span class="ix">0{i+1}</span><div class="txt"><h3 class="serif">{t}</h3><p>{d}</p><a class="cap" href="#" style="border-bottom:1px solid var(--copper);padding-bottom:4px">{l} →</a></div><div class="media">{vid(c)}</div></div>' for i,(t,d,c,l) in enumerate(svc))
steps=[("Get in touch","Reach out via WhatsApp, email, or our contact form with your preferred dates and requirements."),("Proposal","Our team crafts a tailored proposal with yacht selection, itinerary, and all the details."),("Confirm","Review your bespoke package, confirm the booking, and we handle all the preparation."),("On board","Step aboard and enjoy a flawless luxury yacht experience on the waters of Dubai.")]
st=''.join(f'<div><span class="ix">0{i+1}</span><h4 class="serif">{a}</h4><p>{b}</p></div>' for i,(a,b) in enumerate(steps))
open('services/index.html','w').write(head('Services','Services')+f'''<header class="hero short">{vid('evo43-run')}<span class="crumb cap">Home / Services</span><div class="in"><h1 class="serif">Four<br>services.</h1><p>Charter, management, cinematography and branding. One owner-operated team at Dubai Harbour.</p></div></header>
<section><div class="head"><h2 class="serif">What we<br>do.</h2><p>Four pillars covering every aspect of the yachting experience, run on our own fleet.</p></div>{rows}</section>
<section class="light"><div class="head"><h2 class="serif">How it<br>works.</h2><p>From your first inquiry to stepping aboard, we make the process seamless.</p></div><div class="steps">{st}</div></section>
<section><div class="facts cap"><div>Licence<b>960574</b></div><div>Berth<b>Dubai Harbour</b></div><div>Model<b>Owner, not broker</b></div><div>Fleet<b>3 yachts</b></div></div></section>
{cta('moneta-golden','Plan your<br>day on the water.')}'''+FOOT)
import json
F=json.load(open('../prototype/content/fleet.json'))
guests={"monte-carlo-6":"Up to 18"}
def g(y): return guests.get(y['slug']) or (f"Up to {y['guests']}" if y['guests'] else "On request")
ys=''.join(f'''<article class="yacht"><div class="media">{vid(y["clips"][0])}</div><div><span class="ix">0{i+1}</span> <span class="cap" style="color:var(--mute)">{y["builder"]}</span><h3 class="serif">{y["name"]}</h3><div class="spec"><div><span class="cap">Length</span><b>{y["loa"]}</b></div><div><span class="cap">Guests</span><b>{g(y)}</b></div><div><span class="cap">Built / refit</span><b>{y["built"] or "–"}{(" / "+str(y["refit"])) if y["refit"] else ""}</b></div><div><span class="cap">Berth</span><b>{y["berth"]}</b></div></div><p style="margin-top:28px"><a class="btn o" href="#">View yacht</a></p></div></article>''' for i,y in enumerate(F))
open('fleet/index.html','w').write(head('Fleet','Fleet')+f'''<header class="hero">{vid('hero-vd40-speed')}<span class="crumb cap">Home / Fleet</span><div class="in"><h1 class="serif">Our<br>fleet.</h1><p>Premium motor yachts, owned and maintained by us. Fleet owner, not a broker. Berthed at Dubai Harbour, ready for your next day on the water.</p></div></header>
<section><div class="head"><h2 class="serif">Three<br>yachts.</h2><p>Every charter includes crew, fuel and standard amenities.</p></div>{ys}</section>
{cta('vd40-aerial','Which one<br>is yours?')}'''+FOOT)
v=F[0]
faq=[("What types of yachts does Imperial Yachting offer?","Three vessels: the Monte Carlo 6, a 60ft Italian flybridge motor yacht for up to 18 guests; the Van Dutch 40, a 40ft Dutch day cruiser for up to 10 guests; and the EVO 43, a 43ft Italian transformable day yacht with XTension deck."),("Are the yachts available for overnight charters?","The Van Dutch 40 and EVO 43 are primarily day charter vessels, but monthly rentals are available during all seasons. The Monte Carlo 6 is available for overnight and multi-day charters.")]
fq=''.join(f'<details open><summary>{a}</summary><p>{b}</p></details>' for a,b in faq)
inc=["Professional crew","Fuel","Standard amenities","Departure from Dubai Harbour"]
open('fleet-vd-40/index.html','w').write(head('Van Dutch 40','Fleet')+f'''<header class="hero">{vid('hero-vd40-speed')}<span class="crumb cap">Home / Fleet / Van Dutch 40</span><div class="in"><h1 class="serif">Van<br>Dutch 40</h1><p>The iconic 40ft Dutch day cruiser. Up to 10 guests, refitted in 2024, berthed at Dubai Harbour.</p></div></header>
<section><div class="spec spec4"><div><span class="cap">Length</span><b>{v["loa"]}</b></div><div><span class="cap">Guests</span><b>Up to {v["guests"]}</b></div><div><span class="cap">Built / refit</span><b>{v["built"]} / {v["refit"]}</b></div><div><span class="cap">Berth</span><b>{v["berth"]}</b></div></div></section>
<section style="padding:0;height:90vh;position:relative">{vid('vd40-aerial')}</section>
<section class="light"><div class="split"><div><span class="ix">01</span><h2 class="serif" style="font-size:96px;margin-top:12px">What's<br>included.</h2><p style="margin-top:24px;max-width:380px">Every charter comes with these essentials at no extra cost. Rates in AED on request.</p></div><ul class="list">{''.join(f'<li><span class="ix">0{i+1}</span>{x}</li>' for i,x in enumerate(inc))}</ul></div></section>
<section class="sand faq"><div class="head"><h2 class="serif">Questions.</h2><p>Common questions about our fleet and charter options.</p></div>{fq}</section>
{cta('ilia-onboard','Book the<br>Van Dutch 40.')}'''+FOOT)
